class Basket {
  constructor(...items) {
    this.items = items;
  }

  [Symbol.toPrimitive](hint) {
    return hint === "number" ? this.items.length : this.items.join("+");
  }

  get [Symbol.toStringTag]() {
    return "Basket";
  }
}

const basket = new Basket("egg", "jam");

console.log(basket * 10);
console.log(basket + "!");
console.log(Object.prototype.toString.call(basket));
